. jobs_pc/common.sh
# mem: 30
# cpus: 8
# after: 7370_tc_pack_armA,7363_tc_collect_armA
# Arm A: final gates (all seven methods), the one-time score stage (pooled AUPR, 500 gene delete-half replicates, 500 complex-level replicates, per-complex AP, strata, perturbed-gene split), then the report (estimates, H1, H2, H3, descriptors, fixed sentences).
set -e
export OMP_NUM_THREADS=2 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
Rscript analysis/tcaclr_confirm/score_confirm.R --stage gates --arm A --scores results/tcaclr_confirm/armA/scores --truth_dir docs/tcaclr_confirm_selections --members docs/tcaclr_confirm_selections/armA_complex_portal_members.tsv --excluded docs/tcaclr_confirm_selections/armA_complex_portal_excluded_pairs.tsv --sha docs/tcaclr_confirm_selections/armA.sha256 --counts docs/tcaclr_confirm_selections/armA_complex_portal_counts.csv --perturbed docs/tcaclr_confirm_selections/armA_perturbed_genes_networkhalf.txt --out results/tcaclr_confirm/result_A
Rscript analysis/tcaclr_confirm/score_confirm.R --stage score --arm A --scores results/tcaclr_confirm/armA/scores --truth_dir docs/tcaclr_confirm_selections --members docs/tcaclr_confirm_selections/armA_complex_portal_members.tsv --excluded docs/tcaclr_confirm_selections/armA_complex_portal_excluded_pairs.tsv --sha docs/tcaclr_confirm_selections/armA.sha256 --counts docs/tcaclr_confirm_selections/armA_complex_portal_counts.csv --perturbed docs/tcaclr_confirm_selections/armA_perturbed_genes_networkhalf.txt --out results/tcaclr_confirm/result_A --upstream_gates results/tcaclr_confirm/result_A/gates.csv --workers 8
Rscript analysis/tcaclr_confirm/score_confirm.R --stage report --arm A --scores results/tcaclr_confirm/armA/scores --truth_dir docs/tcaclr_confirm_selections --members docs/tcaclr_confirm_selections/armA_complex_portal_members.tsv --excluded docs/tcaclr_confirm_selections/armA_complex_portal_excluded_pairs.tsv --sha docs/tcaclr_confirm_selections/armA.sha256 --counts docs/tcaclr_confirm_selections/armA_complex_portal_counts.csv --perturbed docs/tcaclr_confirm_selections/armA_perturbed_genes_networkhalf.txt --out results/tcaclr_confirm/result_A --upstream_gates results/tcaclr_confirm/result_A/gates.csv
